begin;
-- Positive privileged fixtures represent a completed MFA verification.
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(1);
create function pg_temp.check_true(v boolean) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Profile identity assertion failed';end if;end $$;
insert into auth.users(id,email) values('ef100000-0000-4000-8000-000000000001','admin.profile.qa@example.invalid'),('ef100000-0000-4000-8000-000000000002','staff.profile.qa@example.invalid');
insert into public.employee_directory(id,branch_code,full_name,npp,employment_status,verification_status,is_active) values('ef200000-0000-4000-8000-000000000001','DPS','[CONTOH] Profile QA','99381','active','verified',true);
insert into public.employee_directory(id,branch_code,full_name,npp,employment_status,verification_status,is_active) values('ef200000-0000-4000-8000-000000000002','DPS','[CONTOH] Admin QA','99382','active','verified',true);
insert into public.profiles(id,employee_id,branch_code,full_name,is_active,activated_at) values('ef100000-0000-4000-8000-000000000001','ef200000-0000-4000-8000-000000000002','DPS','[CONTOH] Profile Admin',true,now());
insert into public.user_role_assignments(profile_id,branch_code,role_code,grant_reason) values('ef100000-0000-4000-8000-000000000001','DPS','super_admin','[CONTOH] Rollback profile test');
select set_config('request.jwt.claim.sub','ef100000-0000-4000-8000-000000000001',true);
set local role authenticated;
select public.save_profile_identity('DPS',null,'{"full_name":"[CONTOH] Profile User","email":"staff.profile.qa@example.invalid","npp":"99381","whatsapp":"08123456789","is_active":false}');
select pg_temp.check_true((select employee_id='ef200000-0000-4000-8000-000000000001' and npp='99381' from public.profile_identity_records where id='ef100000-0000-4000-8000-000000000002'));
select public.save_profile_identity('DPS','ef100000-0000-4000-8000-000000000002','{"full_name":"[CONTOH] Updated User","email":"staff.profile.qa@example.invalid","npp":"99381","whatsapp":"08123456780","is_active":false}');
reset role;
update public.employee_directory set npp=null where id='ef200000-0000-4000-8000-000000000001';
set local role authenticated;
select public.save_profile_identity('DPS','ef100000-0000-4000-8000-000000000002','{"full_name":"[CONTOH] Non-NPP User","email":"staff.profile.qa@example.invalid","npp":null,"whatsapp":"08123456780","is_active":true}');
select pg_temp.check_true((select employee_id='ef200000-0000-4000-8000-000000000001' and is_active from public.profiles where id='ef100000-0000-4000-8000-000000000002'));
do $$begin begin perform public.save_profile_identity('DPS',null,'{"full_name":"[CONTOH] Missing","email":"missing.profile.qa@example.invalid","npp":null,"is_active":false}');raise exception 'Expected missing Auth rejection';exception when sqlstate 'P0001' then if sqlerrm='Expected missing Auth rejection' then raise;end if;end;end $$;
select public.save_profile_identity('DPS','ef100000-0000-4000-8000-000000000002','{"employee_id":"ef200000-0000-4000-8000-000000000001","full_name":"Wrong typed name","email":"staff.profile.qa@example.invalid","npp":null,"is_active":true}');
select pg_temp.check_true((select employee_id='ef200000-0000-4000-8000-000000000001' and full_name='[CONTOH] Profile QA' from public.profiles where id='ef100000-0000-4000-8000-000000000002'));
reset role;
insert into public.user_notifications(id,branch_code,profile_id,event_id,title,href) values('ef300000-0000-4000-8000-000000000001','DPS','ef100000-0000-4000-8000-000000000001',gen_random_uuid(),'[CONTOH] Archive QA','/dashboard?branch=DPS');
set local role authenticated;
insert into public.notification_archive_preferences(notification_id,profile_id,archived_at) values('ef300000-0000-4000-8000-000000000001',auth.uid(),now());
select pg_temp.check_true((select user_archived_at is not null from public.notification_user_feed where id='ef300000-0000-4000-8000-000000000001'));
select pg_temp.check_true((select archived_at is null from public.user_notifications where id='ef300000-0000-4000-8000-000000000001'));
update public.notification_archive_preferences set archived_at=null where notification_id='ef300000-0000-4000-8000-000000000001';
select pg_temp.check_true((select user_archived_at is null from public.notification_user_feed where id='ef300000-0000-4000-8000-000000000001'));
select set_config('request.jwt.claim.sub','ef100000-0000-4000-8000-000000000002',true);
do $$begin begin perform public.save_profile_identity('DPS',null,'{}');raise exception 'Expected role denial';exception when insufficient_privilege then null;end;end $$;
do $$begin begin insert into public.notification_archive_preferences(notification_id,profile_id,archived_at) values('ef300000-0000-4000-8000-000000000001',auth.uid(),now());raise exception 'Expected other inbox denial';exception when insufficient_privilege then null;end;end $$;
reset role;
select pass('Profile identity create/edit, NPP mapping, missing Auth and RBAC');
select * from finish();
rollback;
